-- Task management + PAN/GST compliance auto-generation.
--
-- Apply once against the project's Supabase database (SQL editor or
-- `supabase db push`). Everything here is additive — no existing table is
-- altered — so it is safe to run on the live project.
--
--   tasks                 work items, manual or auto-generated by a rule
--   task_events           audit trail of every status / assignment change
--   compliance_snapshots  raw PAN & GST API responses per client, per fetch
--   compliance_runs       one row per sync (cron or manual), with its summary

-- ---------------------------------------------------------------- tasks ----
create table if not exists public.tasks (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.clients (id) on delete cascade,

  title text not null,
  details text,
  -- Rule that produced the task ('gst_return_pending', ...) or 'manual'.
  kind text not null default 'manual',
  -- 'auto'  -> generated from a PAN/GST API snapshot
  -- 'manual'-> created by a person in the CRM
  source text not null default 'manual' check (source in ('auto', 'manual')),
  -- Filing period the task belongs to: '2026-07', '2026-Q2', 'AY 2026-27'.
  period text,

  due_date date,
  priority text not null default 'normal' check (priority in ('high', 'normal', 'low')),
  status text not null default 'open' check (status in ('open', 'in_progress', 'done', 'dismissed')),

  assignee_staff_id uuid references public.staff (id) on delete set null,
  -- Allotment role the auto-assignment came from (partner / gst / income_tax…).
  assigned_role text,

  -- client_id + kind + period. Unique, so a re-run updates rather than
  -- duplicates. NULL for manual tasks (they are never deduped).
  dedupe_key text unique,
  -- The bit of API response the rule fired on, kept so staff can see why.
  evidence jsonb,

  created_by uuid references public.staff (id) on delete set null,
  completed_by uuid references public.staff (id) on delete set null,
  completed_at timestamptz,
  -- Why the task left the open state: 'auto_resolved', 'done', or free text.
  resolution text,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists tasks_client_idx on public.tasks (client_id);
create index if not exists tasks_assignee_idx on public.tasks (assignee_staff_id);
create index if not exists tasks_status_due_idx on public.tasks (status, due_date);
create index if not exists tasks_kind_idx on public.tasks (kind);

-- ---------------------------------------------------------- task_events ----
create table if not exists public.task_events (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.tasks (id) on delete cascade,
  actor_staff_id uuid references public.staff (id) on delete set null,
  -- 'created' | 'status' | 'assigned' | 'auto_updated' | 'auto_resolved'
  action text not null,
  note text,
  created_at timestamptz not null default now()
);

create index if not exists task_events_task_idx on public.task_events (task_id, created_at desc);

-- ------------------------------------------------- compliance_snapshots ----
create table if not exists public.compliance_snapshots (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.clients (id) on delete cascade,
  run_id uuid,
  -- 'gst' (GSTIN lookup + return filing history) or 'pan'
  kind text not null check (kind in ('gst', 'pan')),
  identifier text not null,
  provider text not null,
  ok boolean not null default false,
  payload jsonb,
  error text,
  fetched_at timestamptz not null default now()
);

create index if not exists compliance_snapshots_client_idx
  on public.compliance_snapshots (client_id, kind, fetched_at desc);

-- ------------------------------------------------------ compliance_runs ----
create table if not exists public.compliance_runs (
  id uuid primary key default gen_random_uuid(),
  trigger text not null default 'manual' check (trigger in ('cron', 'manual')),
  dry_run boolean not null default false,
  actor_staff_id uuid references public.staff (id) on delete set null,
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  summary jsonb,
  error text
);

create index if not exists compliance_runs_started_idx on public.compliance_runs (started_at desc);

-- ------------------------------------------------------------------ RLS ----
-- Same model as the rest of the CRM: any signed-in staff member can read and
-- work on tasks; only admins may hard-delete. The cron uses the service role
-- key, which bypasses RLS.
alter table public.tasks enable row level security;
alter table public.task_events enable row level security;
alter table public.compliance_snapshots enable row level security;
alter table public.compliance_runs enable row level security;

create or replace function public.is_staff() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.staff where auth_user_id = auth.uid());
$$;

create or replace function public.is_admin_staff() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.staff where auth_user_id = auth.uid() and app_role = 'admin'
  );
$$;

do $$
begin
  if not exists (select 1 from pg_policies where tablename = 'tasks' and policyname = 'tasks_read') then
    create policy tasks_read on public.tasks for select to authenticated using (public.is_staff());
  end if;
  if not exists (select 1 from pg_policies where tablename = 'tasks' and policyname = 'tasks_write') then
    create policy tasks_write on public.tasks for insert to authenticated with check (public.is_staff());
  end if;
  if not exists (select 1 from pg_policies where tablename = 'tasks' and policyname = 'tasks_update') then
    create policy tasks_update on public.tasks for update to authenticated
      using (public.is_staff()) with check (public.is_staff());
  end if;
  if not exists (select 1 from pg_policies where tablename = 'tasks' and policyname = 'tasks_delete') then
    create policy tasks_delete on public.tasks for delete to authenticated using (public.is_admin_staff());
  end if;

  if not exists (select 1 from pg_policies where tablename = 'task_events' and policyname = 'task_events_read') then
    create policy task_events_read on public.task_events for select to authenticated using (public.is_staff());
  end if;
  if not exists (select 1 from pg_policies where tablename = 'task_events' and policyname = 'task_events_write') then
    create policy task_events_write on public.task_events for insert to authenticated with check (public.is_staff());
  end if;

  if not exists (select 1 from pg_policies where tablename = 'compliance_snapshots' and policyname = 'compliance_snapshots_read') then
    create policy compliance_snapshots_read on public.compliance_snapshots
      for select to authenticated using (public.is_staff());
  end if;
  if not exists (select 1 from pg_policies where tablename = 'compliance_snapshots' and policyname = 'compliance_snapshots_write') then
    create policy compliance_snapshots_write on public.compliance_snapshots
      for insert to authenticated with check (public.is_staff());
  end if;

  if not exists (select 1 from pg_policies where tablename = 'compliance_runs' and policyname = 'compliance_runs_read') then
    create policy compliance_runs_read on public.compliance_runs
      for select to authenticated using (public.is_staff());
  end if;
  if not exists (select 1 from pg_policies where tablename = 'compliance_runs' and policyname = 'compliance_runs_write') then
    create policy compliance_runs_write on public.compliance_runs
      for insert to authenticated with check (public.is_staff());
  end if;
  if not exists (select 1 from pg_policies where tablename = 'compliance_runs' and policyname = 'compliance_runs_update') then
    create policy compliance_runs_update on public.compliance_runs
      for update to authenticated using (public.is_staff()) with check (public.is_staff());
  end if;
end $$;
